(ns armate.archimate.core (:require [clojure.string :as s] [armate.archimate.collector :as acl] [armate.archimate.metamodel.derivation.core :as dcr] [armate.archimate.metamodel.meta :as mt] [armate.archimate.viz.saver :as svr] [armate.archimate.multi-graph :as mg] [armate.archimate.archi.parser :as arr] [armate.archimate.plantuml.parser :as prr] [armate.archimate.viz.align.neighbours :as alg] [armate.archimate.viz.combiner :as viz]))
(defn layer? [layer kind] (s/starts-with? (name kind) (name layer)))
(defn get-stats [context] (let [relations (mg/get-relationships (:relations context)) groups (group-by (comp :derivate last) relations)] {:types (count (:types context)), :elements (count (:elements context)), :relations {:original (count (groups nil [])), :nesting (count (groups :nesting [])), :certain (count (groups :certain [])), :potential (count (groups :potential []))}, :lints (count (:lints context))}))
(defn analyze-file [file-path] (let [content (slurp file-path)] (if (empty? content) (throw (ex-info "File is empty" {:file-path file-path})) (prr/analyze-content content))))
(defn stat-file [file-path] (try (-> file-path analyze-file dcr/derivate-relations get-stats) (catch clojure.lang.ExceptionInfo e {:exception {:message (ex-message e), :data (ex-data e)}})))
(defn find-alias [context name] (some (fn* [%1] (when (= name (:name (second %1))) (first %1))) (:elements context)))
(defn convert-path [context path] (reduce (fn [acc item] (if (vector? item) (-> acc (conj (get-in context [:elements (first item) :name])) (conj (select-keys (second item) [:type :kind]))) (conj acc (get-in context [:elements item :name])))) [] path))
(defn filter-elements [context key predicate] (update context key (partial reduce-kv (fn [acc alias element] (if (predicate (:kind element)) (assoc acc alias element) acc)) {})))
(defn filter-relationships [context key predicate] (update context key (partial mg/filter-relationships predicate)))
(defn erase-transitive-rels [context rel-types] (reduce (fn [acc rel-type] (update acc :relations (partial mg/erase-transitive-relationships rel-type))) context rel-types))
(defn generate-derivate-context ([context predicate out-path] (generate-derivate-context context identity predicate out-path)) ([context element-predicate relation-predicate out-path] (try (-> context (dissoc :connectors) (dissoc :misc) (filter-elements :elements element-predicate) (filter-relationships :relations relation-predicate) (erase-transitive-rels [:realization :aggregation :composition :specialization]) (svr/save-puml out-path false)) (catch clojure.lang.ExceptionInfo e {:msg (ex-message e), :data (ex-data e)}))))
(defn generate-derivate-file [predicate file-path name-suffix] (generate-derivate-context (analyze-file file-path) predicate (svr/add-suffix file-path name-suffix)))
(comment)
